// OperatorConsoleServer is the server API for OperatorConsole service.
// All implementations must embed UnimplementedOperatorConsoleServer
// for forward compatibility.
//
// OperatorConsole is the operator-plane service for the Cambrian UI (ADR-0047).
// It is distinct from the agent-facing Orchestrator/AgentService: its audience
// is a human Operator/Viewer, not an agent (no x-agent-id principal). This file
// holds the sequenced event feed (issue 0047-01); snapshots, commands, and auth
// are added by later slices.
type OperatorConsoleServer interface {
	// Login authenticates a human operator (username/password) and returns a
	// token bound to {principal, role}. The only unauthenticated RPC. ADR-0047 D13.
	Login(context.Context, *LoginRequest) (*LoginResponse, error)
	// StreamEvents drains the sequenced operator feed. The client resumes from
	// last_seq; every OperatorEvent carries a global monotonic seq (the cursor).
	StreamEvents(*SubscribeRequest, grpc.ServerStreamingServer[OperatorEvent]) error
	// Snapshot returns bounded live operational state (plans in flight, sessions)
	// stamped with a lower-bound as_of_seq. The client resumes StreamEvents from
	// as_of_seq+1; idempotent absolute-state events make the overlap harmless.
	// Large/historical data is NOT here — paged read RPCs serve it. ADR-0047 D6/D8.
	Snapshot(context.Context, *SnapshotRequest) (*SnapshotResponse, error)
	// SetToolGrant grants or revokes a system tool for an agent (Operator-only).
	// Idempotent (command_id), mandatory reason, audited. ADR-0047 D7/D15.
	SetToolGrant(context.Context, *SetToolGrantRequest) (*CommandAck, error)
	// QueryAudit reads the operator_audit log, filtered + paginated. Read RPC
	// (any authenticated role). Never folded into Snapshot. ADR-0047 D8/0047-08.
	QueryAudit(context.Context, *QueryAuditRequest) (*QueryAuditResponse, error)
	// ResolveHITL approves/rejects a raised HITL intervention (Operator-only).
	// Idempotent on the intervention id via command_id. ADR-0047 D11/0047-09.
	ResolveHITL(context.Context, *ResolveHITLRequest) (*CommandAck, error)
	// PauseSession / ResumeSession steer a live execution via the control hub AND persist
	// the session's lifecycle status, so the operator console's state reflects the command
	// (Phase 2). Before this they only signalled an in-memory executor, so a paused session
	// still reported "active" and could never be resumed from the console.
	PauseSession(context.Context, *SessionCommandRequest) (*CommandAck, error)
	ResumeSession(context.Context, *SessionCommandRequest) (*CommandAck, error)
	// CloseSession seals a session (→ completed). It is the terminator the lifecycle never
	// had: without it nothing ever left "active", so episodic consolidation (ADR-0012/0030)
	// was gated on a state no code could reach. Idempotent via command_id; audited.
	CloseSession(context.Context, *SessionCommandRequest) (*CommandAck, error)
	// Remaining mutations (Operator-only, idempotent, audited). ADR-0047 0047-07.
	TagMemory(context.Context, *TagMemoryRequest) (*CommandAck, error)
	SetScope(context.Context, *SetScopeRequest) (*CommandAck, error)
	RegisterSkill(context.Context, *RegisterSkillRequest) (*CommandAck, error)
	RegisterMCP(context.Context, *RegisterMCPRequest) (*CommandAck, error)
	TriggerConsolidation(context.Context, *TriggerConsolidationRequest) (*CommandAck, error)
	// SetRuntimeConfig hot-applies numeric runtime tunables (e.g. the Stage-A blend
	// weights) to the live kernel WITHOUT a restart — the automated-tuning seam
	// (ADR-0054). Idempotent (command_id), mandatory reason, audited, Operator-only.
	// Ephemeral: edits live in memory; config.json stays the boot default.
	SetRuntimeConfig(context.Context, *SetRuntimeConfigRequest) (*CommandAck, error)
	// Chat & steer (Operator-only, audited). ADR-0047 0047-10.
	CreateSession(context.Context, *CreateSessionRequest) (*CreateSessionResponse, error)
	SendMessage(context.Context, *SendMessageRequest) (*CommandAck, error)
	InjectCorrection(context.Context, *InjectCorrectionRequest) (*CommandAck, error)
	// ── Conversations — the OSS chat lane (ADR-0084 D9). Distinct from CreateSession/
	// SendMessage above, which drive the TASK planner: a conversational turn is owned by a
	// single agent loop on the kernel's chat worker pool and is NEVER decomposed into a plan
	// (ADR-0080). SendTurn is synchronous — it returns the agent's reply message. The owner
	// of a conversation is the resolved operator principal, never the request body.
	// Capability "chat", advertised only when the chat lane is wired
	// (execution.chat_pool_size > 0 + a conversation store); OSS otherwise ⇒ Unimplemented.
	OpenConversation(context.Context, *OpenConversationOpRequest) (*OpenConversationOpResponse, error)
	SendTurn(context.Context, *SendTurnOpRequest) (*SendTurnOpResponse, error)
	CloseConversation(context.Context, *CloseConversationOpRequest) (*CommandAck, error)
	// Read RPCs (no command_id). ListConversations enumerates the calling operator's own
	// conversations (most recently updated first) for a ChatGPT-style sidebar;
	// ListConversationMessages returns one conversation's transcript, ordered, after a seq.
	ListConversations(context.Context, *ListConversationsOpRequest) (*ListConversationsOpResponse, error)
	ListConversationMessages(context.Context, *ListConversationMessagesOpRequest) (*ListConversationMessagesOpResponse, error)
	// Paged reads (any authenticated role; never folded into Snapshot). A2.1/D8.
	ListTools(context.Context, *ListToolsOpRequest) (*ListToolsOpResponse, error)
	ListSkills(context.Context, *ListSkillsOpRequest) (*ListSkillsOpResponse, error)
	QueryMemory(context.Context, *QueryMemoryRequest) (*QueryMemoryResponse, error)
	// ListDocuments enumerates ingested documents by ROW, not by relevance.
	//
	// QueryMemory is semantic: it answers "find the document that says X". That is the
	// wrong instrument for classification, which asks "which of my documents have no
	// labels?" — a question with no query text, because the operator does not yet know
	// what those documents say. Access policy acts only on labels, so an unlabelled
	// document is not denied, it is INVISIBLE to the policy model; without an
	// enumeration there was no way to find one except by already knowing its contents.
	//
	// Reads the `documents` table directly (small, GIN-indexed on tags). Documents are
	// an OSS concept — the store owns them with or without the policy plugin — so this
	// lives on the OSS plane rather than behind access-policy. Read RPC (any
	// authenticated role, no command_id).
	ListDocuments(context.Context, *ListDocumentsOpRequest) (*ListDocumentsOpResponse, error)
	// GetDocument fetches ONE document by id, body included.
	//
	// The keyed read the memory lane never had. ListDocuments above is keyed but
	// returns a listing row — "no body, no chunks" by its own contract — and
	// QueryMemory returns the body but is RANKED. Nothing joined them, so resolving
	// an id to its text meant searching semantically for an opaque token and hoping
	// it ranked. That is not a retrieval-quality problem a larger top-k fixes: there
	// is no question to rank against. It was a missing primitive.
	//
	// Two callers need it. A drift alert cites a message id, and a console that
	// cannot open that message shows a citation nobody can follow. And a watch whose
	// signal carries REFERENCES ONLY (the ingress contract) must resolve the
	// reference to content it can read — which is the property that makes a replayed
	// signal resolve today's document rather than a stale copy in the payload.
	GetDocument(context.Context, *GetDocumentOpRequest) (*GetDocumentOpResponse, error)
	// AnswerMemory (ADR-0081) runs the agentic retrieval loop and returns a GROUNDED
	// composed answer with inline [n] citation markers, plus the evidence each marker
	// resolves to. Distinct from QueryMemory's single-pass evidence lane: this is a
	// read that synthesizes (no auction, no mutation, no x-agent-id principal). Gated
	// on the "memory-answer" capability; OSS / agentic-disabled builds return
	// Unimplemented.
	AnswerMemory(context.Context, *AnswerMemoryRequest) (*AnswerMemoryResponse, error)
	// Tool permission management: bound an existing grant with a resource policy
	// (Operator-only, idempotent, audited). A2.3.
	SetToolPolicy(context.Context, *SetToolPolicyRequest) (*CommandAck, error)
	// Operator-triggered tool execution at ScopeSystem — a deliberate grant
	// bypass, audited, dangerous tools also emit a feed event (Operator-only). A2.2.
	ExecuteTool(context.Context, *ExecuteToolOpRequest) (*ExecuteToolOpResponse, error)
	// Memory ingest through the kernel ingest path (operator as Author; never a
	// raw store write). Idempotent on command_id (Operator-only, audited). A2.4.
	IngestMemory(context.Context, *IngestMemoryOpRequest) (*IngestMemoryOpResponse, error)
	// Tool-approval stream mirroring the ADR-0039 dangerous-tool approval request
	// (Operator-only). Resolve reuses ResolveHITL over the shared ApprovalHub
	// id-space. A2.5.
	WatchToolApprovals(*SubscribeRequest, grpc.ServerStreamingServer[ApprovalOp]) error
	// ── Watch surfaces — PREMIUM capability-gated (D14/A2.6). The proto lives in
	// OSS in full (defining ≠ implementing); OSS handlers return Unimplemented and
	// the WatchTriggered class never publishes. Advertised only on premium builds.
	ListWatches(context.Context, *ListWatchesOpRequest) (*ListWatchesOpResponse, error)
	RegisterWatch(context.Context, *RegisterWatchOpRequest) (*CommandAck, error)
	DeleteWatch(context.Context, *DeleteWatchOpRequest) (*CommandAck, error)
	SetWatchActive(context.Context, *SetWatchActiveOpRequest) (*CommandAck, error)
	// ListWatchDeadLetters reads reactive actions that could not be delivered — a
	// failed action or a journal signal that expired before it ran (REACT-01 /
	// ADR-0061). Read RPC (no command_id). Capability "watch-deadletter", advertised
	// on premium builds; OSS returns an empty list (no reactive engine writes them).
	ListWatchDeadLetters(context.Context, *ListWatchDeadLettersOpRequest) (*ListWatchDeadLettersOpResponse, error)
	// ── Reactive pipelines (contract 0087, ADR-0114 D33/D34) ──────────────────
	//
	// A pipeline is not a watch. A watch is one condition and a list of arms; a
	// pipeline is an authored, versioned GRAPH with typed ports, declared
	// discards and a durable execution store behind it. They are listed
	// separately because collapsing them would force one shape to lie about the
	// other — a watch has no revisions and no nodes, a pipeline has no single
	// condition.
	//
	// Every ingress created through the Ingress Studio owns one, generated from
	// its mapping and armed with the ingress (D34). An ingress that has not been
	// armed has NO armed pipeline, and that is a normal state, not a fault.
	//
	// Read RPC (no command_id). Capability "reactive-pipelines", advertised on
	// premium builds; OSS returns an empty list.
	ListPipelines(context.Context, *ListPipelinesOpRequest) (*ListPipelinesOpResponse, error)
	// DryRunPipeline replays captured deliveries through the compiled plan with
	// every effect shadowed: every gate, branch, aggregate and key derivation runs
	// for real, and nothing reaches the world.
	//
	// The substitution is at the DISPATCHER and nowhere earlier, which is what
	// makes the report worth reading — effect-key derivation, projection identity
	// and barrier obligations all execute, so a duplicate key surfaces here rather
	// than as missing knowledge weeks later.
	//
	// Distinct from BacktestWatch, which asks a different question: a dry run asks
	// what this would do to what is arriving now; a backtest replays journaled
	// history to argue for a change. Neither ever executes an arm.
	//
	// Read RPC (no command_id) — it performs nothing. Capability
	// "reactive-pipelines"; OSS REFUSES by name rather than answering with an
	// empty report, because "nothing would happen" is not a true answer on a build
	// that cannot run one.
	DryRunPipeline(context.Context, *DryRunPipelineOpRequest) (*DryRunPipelineOpResponse, error)
	// GetPipeline returns one authored revision as authored, plus what the
	// compiler says about it right now.
	//
	// The refusals travel with the READ, not only with an edit: a stored revision
	// can stop compiling without anyone touching it — a ceiling lowered, a node
	// kind retired — and a console that validated only on edit would offer to
	// publish it.
	//
	// Read RPC (no command_id). Capability "reactive-pipelines".
	GetPipeline(context.Context, *GetPipelineOpRequest) (*GetPipelineOpResponse, error)
	// ListNodeItems returns what actually reached one node, newest first.
	//
	// The inspector could say a node RAN and never what ran through it: an
	// operator watching their own data flow saw `save_to_memory → out "effect
	// confirmed"` and not one value that landed. Every task already carried its
	// input envelope, its result and its evidence — this is the read that was
	// missing, not the data.
	//
	// Read RPC (no command_id). Capability "reactive-pipelines".
	ListNodeItems(context.Context, *ListNodeItemsOpRequest) (*ListNodeItemsOpResponse, error)
	// ValidatePipeline compiles a graph document WITHOUT storing it, so an editor
	// can ask on every change.
	//
	// Deliberately separate from the lifecycle's own validate step, which
	// transitions a stored revision. This one has no side effect of any kind: an
	// editor that could accidentally publish is a worse editor, and the safest
	// way to guarantee it cannot is to give it an RPC that has no power to.
	//
	// Read RPC (no command_id) — it stores nothing.
	ValidatePipeline(context.Context, *ValidatePipelineOpRequest) (*ValidatePipelineOpResponse, error)
	// SavePipeline stores an edited graph as a new DRAFT revision.
	//
	// It can create a draft and nothing else. Publishing and arming stay on the
	// lifecycle, where each is an explicit act with its own gate — a canvas that
	// could arm what it had just drawn would collapse four deliberate steps into
	// one mouse click.
	//
	// A graph that breaks rules is still stored. An operator mid-edit needs to
	// keep their work, and a draft cannot run; what refusals block is publishing.
	//
	// Capability "reactive-pipelines".
	SavePipeline(context.Context, *SavePipelineOpRequest) (*SavePipelineOpResponse, error)
	// TransitionPipeline moves ONE revision along its lifecycle: draft →
	// validated → published → armed; armed → published is the pause; retired
	// ends it (contract 0093).
	//
	// This is the button SavePipeline deliberately is not. Each gate still
	// holds — a revision that does not compile refuses to validate, publishing
	// requires validated, arming requires published and disarms the incumbent —
	// and a refusal names the gate in the registry's own words. `armed` walks a
	// draft through validate and publish on the way, because "make THIS live"
	// is one operator intent and answering it with two missing prerequisite
	// buttons would be a bare precondition, not an answer.
	//
	// Capability "pipeline-lifecycle".
	TransitionPipeline(context.Context, *TransitionPipelineOpRequest) (*TransitionPipelineOpResponse, error)
	// ── Kernel logs (contract 0082) ───────────────────────────────────────────
	//
	// OPERATOR-ONLY, both of them. A log line carries whatever the kernel happened
	// to write — ids, request shapes, sometimes content — and it bypasses the
	// access-policy plane entirely, so it is not filtered per principal the way a
	// memory read is. Until it can be, a Viewer does not get it. The auth gate
	// lists these explicitly because the convention there would otherwise open any
	// method named Query* to a Viewer by its spelling alone.
	//
	// Both read the kernel's in-process retention window, which is BOUNDED and
	// does not survive a restart. `LogWindowOp` travels with every response so a
	// console can state that rather than presenting a truncated window as the
	// whole story.
	QueryLogs(context.Context, *QueryLogsOpRequest) (*QueryLogsOpResponse, error)
	TailLogs(*TailLogsOpRequest, grpc.ServerStreamingServer[LogRecordOp]) error
	// REACT-05 / ADR-0071: watch observability. GetWatchMetrics returns per-watch fire/
	// suppression/dry-run/dead-letter counters + mean condition latency. BacktestWatch
	// replays the signal journal through a candidate watch config and reports would-fires
	// WITHOUT acting. Capability "watch-observability"; premium (OSS ⇒ Unimplemented).
	GetWatchMetrics(context.Context, *GetWatchMetricsOpRequest) (*GetWatchMetricsOpResponse, error)
	BacktestWatch(context.Context, *BacktestWatchOpRequest) (*BacktestWatchOpResponse, error)
	// PreviewRoute (ROUTE-07 / ADR-0077) runs the Gatekeeper's L3 merit scoring over a
	// caller-supplied candidate set (inline synthetic profiles) for a step's required
	// capabilities, and returns the ranked funnel — WITHOUT the planner, an auction, or
	// agent execution. It is the gatekeeper-benchmark entry point: deterministic routing
	// data-generation + evaluation, under the active scorer arm (hand weights or the
	// ROUTE-07 learned scorer). Capability "route-preview"; nil-in-OSS ⇒ Unimplemented.
	PreviewRoute(context.Context, *PreviewRouteOpRequest) (*PreviewRouteOpResponse, error)
	// ExplainAccess (ADR-0085 D8) answers "why can / can't this principal reach this
	// resource?" WITHOUT performing the access. It is the gpresult / Azure "Check
	// access" analogue: the reply names the reason, the specific tag or effect
	// responsible, and which policy — linked where — contributed it.
	//
	// Explainability is not a debugging aid here. A fail-closed access model with
	// policy composition multiplies the ways to reach an empty result set by
	// accident, and an unexplained empty result is indistinguishable from "there is
	// no data". Capability "access-policy"; nil-in-OSS ⇒ Unimplemented, because an
	// unscoped deployment has no policy to explain.
	ExplainAccess(context.Context, *ExplainAccessOpRequest) (*ExplainAccessOpResponse, error)
	// ListClassificationTags (ADR-0085 D11) returns the controlled classification
	// vocabulary, so a policy UI offers SELECTION rather than free text. A free-text
	// tag field is a defect: a typo is the primary route to a scope that silently
	// matches nothing. Capability "access-policy"; nil-in-OSS ⇒ Unimplemented.
	ListClassificationTags(context.Context, *ListClassificationTagsOpRequest) (*ListClassificationTagsOpResponse, error)
	// ListSessionCheckpoints reads the checkpoints written as a session executes.
	//
	// Checkpoints are keyed by RUN, not by session: a session accumulates many runs
	// and a step index only means anything relative to the plan of the run it was
	// taken against. A response therefore carries run_id on every row, and a
	// console must group by it — flattening a session's checkpoints into one
	// timeline offers a resume from the wrong plan.
	//
	// Read RPC (no command_id). OSS: served whenever a checkpoint store is wired.
	ListSessionCheckpoints(context.Context, *ListSessionCheckpointsOpRequest) (*ListSessionCheckpointsOpResponse, error)
	// ListMCPServers enumerates the external MCP servers this kernel consumes tools
	// from (ADR-0043), with live connection state.
	//
	// It exists because "0 MCP servers" and "this kernel cannot report MCP servers"
	// are different facts an operator must be able to tell apart, and before this
	// RPC the console could not: there was no read and no feed event, so the
	// surface listed zero on every deployment forever.
	ListMCPServers(context.Context, *ListMCPServersOpRequest) (*ListMCPServersOpResponse, error)
	// GetEmbeddingConfig reports the embedding model, its dimensions and the stored
	// vector count.
	//
	// The pairing matters more than the fields: changing the model WITHOUT
	// re-embedding leaves every stored vector meaningless and NOTHING errors —
	// retrieval starts returning near-random chunks and grounded answers stay
	// confidently wrong, citations and all. Any future model-change RPC must carry
	// the re-embed with it.
	GetEmbeddingConfig(context.Context, *GetEmbeddingConfigOpRequest) (*EmbeddingConfigOp, error)
	// ClassifyInput returns the ADR-0031 router's decision for a typed sentence
	// WITHOUT acting on it, so a console can show what is about to happen and offer
	// one click to overrule it.
	//
	// The classification vocabulary is FIVE values, not three: chat, plan, ingest,
	// watch, clarification. `ingest` is the one a client must not collapse into
	// another — it WRITES to memory, so rendering it as a read makes an operator
	// approve a write believing they approved a question.
	ClassifyInput(context.Context, *ClassifyInputOpRequest) (*ClassifiedInputOp, error)
	// ListGenerators reports the configured LLM generators (ADR-0042) with live
	// breaker state, and ListRoleAssignments which generator serves each system
	// organ (planner / verifier / router / interview / memory).
	//
	// No credential is ever returned: a generator carries key_configured and
	// key_last_four only. There is deliberately no GetGeneratorKey — a console that
	// can display a credential leaks it to whoever is looking at the screen, to a
	// screen recording, and to whatever logged the response, none of which is
	// recoverable.
	ListGenerators(context.Context, *ListGeneratorsOpRequest) (*ListGeneratorsOpResponse, error)
	ListRoleAssignments(context.Context, *ListRoleAssignmentsOpRequest) (*ListRoleAssignmentsOpResponse, error)
	// TestGenerator makes ONE real call against a configured generator's live
	// endpoint.
	//
	// The field that earns this RPC is model_served: the model string the endpoint
	// ECHOED BACK, not the one that was asked for. An endpoint answering happily
	// with a different build is the most common misconfiguration in this space and
	// nothing else in the console would ever reveal it.
	TestGenerator(context.Context, *TestGeneratorOpRequest) (*GeneratorTestResultOp, error)
	// GetConfigSchema is the READ half of the runtime-config surface.
	//
	// SetRuntimeConfig has been able to write a tunable since contract 0047 and
	// nothing could read one back, so a console could only display the kernel's
	// documented defaults and label them a guess.
	//
	// value_source is the field that earns this RPC. It closes the worst
	// configuration bug there is — you change a value, it saves, and nothing
	// happens because something upstream pins it — by naming the layer actually
	// supplying each key, so a pinned field renders read-only NAMING THE PIN.
	//
	// Read RPC (no command_id).
	GetConfigSchema(context.Context, *GetConfigSchemaOpRequest) (*ConfigSchemaOp, error)
	// SetConfig durably records operator configuration intent (ADR-0101).
	//
	// Distinct from SetRuntimeConfig, and both must survive. SetRuntimeConfig is
	// the ADR-0054 automated-tuning seam: ephemeral, keyed by param name, and
	// written by a tuner that must NOT leave permanent marks on a deployment.
	// SetConfig is a human saying "make it this, and keep it this way" — it is
	// keyed by config path and outlives the process.
	//
	// Per-key outcomes rather than one ack, because a partial set can partly
	// succeed. Collapsing that into a single ok/fail hides WHICH field did not
	// take, which is the state an operator most needs to see.
	//
	// Mutating: command_id + reason, audited, Operator-only.
	SetConfig(context.Context, *SetConfigOpRequest) (*SetConfigOpResponse, error)
	// DeleteConfig removes a stored override, reverting the key to whatever the
	// layers beneath the store supply.
	//
	// It is not a convenience. Once a durable write path exists, "put it back" has
	// no other expression: writing the old value over the top leaves the key
	// pinned by the store, so the file or default underneath it stays overridden
	// and a later change to that file silently does nothing.
	DeleteConfig(context.Context, *DeleteConfigOpRequest) (*SetConfigOpResponse, error)
	// SetGeneratorKey / ClearGeneratorKey store an LLM provider credential
	// (ADR-0101 D5). Write-only by construction: there is no getter anywhere on
	// this plane, and the stored value is encrypted at rest.
	//
	// Mutating: command_id + reason, audited. The key itself is never echoed back
	// and never appears in the audit record — only the fact that one was set.
	SetGeneratorKey(context.Context, *SetGeneratorKeyOpRequest) (*SetConfigOpResponse, error)
	ClearGeneratorKey(context.Context, *ClearGeneratorKeyOpRequest) (*CommandAck, error)
	// SaveGenerator / RemoveGenerator are the WRITE half of the generator surface
	// (contract 0083). They land on the ADR-0101 store, which is what the read
	// half's comment has been waiting for — editing configs/providers.json from
	// the operator plane is the thing that store exists to stop.
	//
	// The stored value is the WHOLE generator list, not one entry, because the
	// store layer merges per key and koanf replaces a list wholesale: writing a
	// single generator would delete every other one. Save therefore reads the
	// effective list, applies the edit, and stores the result.
	//
	// The effect is restart_required, and that is reported rather than smoothed
	// over: generators are constructed once, at boot, into the provider's routing
	// table. Claiming `live` here would leave an operator watching traffic go to a
	// model they believe they replaced.
	//
	// Mutating: command_id + reason, audited, Operator-only.
	SaveGenerator(context.Context, *SaveGeneratorOpRequest) (*SetConfigOpResponse, error)
	RemoveGenerator(context.Context, *RemoveGeneratorOpRequest) (*SetConfigOpResponse, error)
	// SubmitPlan runs an OPERATOR-AUTHORED plan, skipping the planner.
	//
	// Every field of AuthoredStepOp maps onto domain.Step, so this is a face for
	// the plan schema rather than a second one. Notably the soft/hard agent pin is
	// already two fields in the domain (ADR-0096): preferred_agent goes first but
	// ranking still runs behind it, agent_pin makes the step DIE if that agent is
	// unavailable. Collapsing them would lose the distinction the design turns on.
	//
	// dry_run validates and estimates WITHOUT creating a session, starting a plan
	// or spending anything. It is not a courtesy: an operator-authored DAG can
	// carry a dependency cycle, which the planner path cannot produce, so the
	// validation it performs has no other home.
	//
	// Mutating: command_id + reason, audited, Operator-only.
	SubmitPlan(context.Context, *SubmitPlanOpRequest) (*SubmitPlanOpResponse, error)
	// GetReactiveBudget reports the reactive plane's running totals against its
	// caps (contract 0074).
	//
	// ReactiveBudgetOp on the feed is a SHED event — it fires once the plane is
	// already dropping work. This is the approach to that line, which is what lets
	// an operator act before the shedding starts rather than after.
	//
	// Read RPC (no command_id). Premium; OSS returns Unimplemented.
	GetReactiveBudget(context.Context, *GetReactiveBudgetOpRequest) (*GetReactiveBudgetOpResponse, error)
	// GetTokenSeries returns recent hourly token usage for the spend sparkline
	// (contract 0075).
	//
	// Tokens only. There is no cost, currency or rate field anywhere in the
	// response: a completion response carries token COUNTS and never a price, so a
	// money figure would be one the kernel invented from an unreconciled rate —
	// a wrong-units bug rather than a rounding one.
	//
	// Read RPC (no command_id).
	GetTokenSeries(context.Context, *GetTokenSeriesOpRequest) (*GetTokenSeriesOpResponse, error)
	// ProposePlan turns a goal into a plan WITHOUT committing to it.
	//
	// The load-bearing property is what it does NOT do: no session is created, no
	// plan is started, nothing is spent. `CreateSession` + `SendMessage` commit;
	// this is where work is SHAPED, and the session begins on approval. A console
	// that promises "nothing committed yet" needs an RPC that honours it.
	//
	// A vague goal comes back as QUESTIONS rather than a bad plan. Planner output
	// is the ceiling on routing quality (ADR-0100 D3), so vagueness cannot be
	// recovered downstream — asking is cheaper than planning badly, and that makes
	// the questions a feature rather than a delay.
	//
	// Read-shaped: no command_id, because nothing is mutated.
	ProposePlan(context.Context, *ProposePlanOpRequest) (*ProposePlanOpResponse, error)
	// ExplainAccessBatch answers many access questions in ONE call, so a
	// reachability matrix can be authoritative instead of predicted.
	//
	// It exists to delete a client-side re-implementation. A console rendering an
	// NxM grid cannot make NxM round trips, so it evaluates the policy set itself —
	// which is a SECOND implementation of access-control logic, and a wrong
	// "allowed" cell there is a security-shaped bug rather than a cosmetic one.
	// Every cell answered by this RPC is answered by the same decision point the
	// enforcement path asks, so the two cannot disagree.
	//
	// Read RPC (no command_id). Bounded server-side; see the request's `queries`.
	ExplainAccessBatch(context.Context, *ExplainAccessBatchOpRequest) (*ExplainAccessBatchOpResponse, error)
	// GetBlastRadiusPreview reports what a scope or grant mutation would do to
	// AGENTS and IN-FLIGHT PLANS, before it is applied.
	//
	// Distinct from the policy blast radius the scope screens already compute:
	// that one answers "how many documents does this rule touch?" from the
	// document listing. This one answers "whose reach changes, and which running
	// plans have to be re-evaluated?" — a different question with a different
	// source, and the only one that can tell an operator they are about to widen
	// an agent mid-plan.
	//
	// An EMPTY preview understates the radius, which is the one direction this
	// number must never be wrong in. A kernel that cannot compute it returns
	// Unimplemented rather than an empty answer.
	//
	// Read RPC (no command_id): it previews, it does not apply.
	GetBlastRadiusPreview(context.Context, *BlastRadiusPreviewOpRequest) (*BlastRadiusPreviewOp, error)
	// RetryWatchDeadLetter replays one dead-lettered reactive action.
	//
	// Safe because REACT-01 (ADR-0061) already records the idempotency key with the
	// dead letter, so the replay runs under the original key and a double-click
	// cannot double-fire. Mutating: command_id + reason, audited. Premium
	// (capability "watch-deadletter"); OSS returns Unimplemented.
	RetryWatchDeadLetter(context.Context, *RetryWatchDeadLetterOpRequest) (*CommandAck, error)
	mustEmbedUnimplementedOperatorConsoleServer()
}

